fun main(){val allowed=booleanArrayOf(true,false,true,true,false);val chosen=booleanArrayOf(false,false,true,false,false);TransferSelectionRules.change(allowed,chosen,0);check(chosen.contentEquals(booleanArrayOf(true,false,true,true,false)));TransferSelectionRules.change(allowed,chosen,2);check(chosen.none{it});TransferSelectionRules.change(allowed,chosen,2);check(chosen.contentEquals(booleanArrayOf(true,false,true,true,false)));TransferSelectionRules.change(allowed,chosen,1);check(TransferSelectionRules.count(chosen)==0);println("PASS: checklist all/none/inverse, disabled events and empty selection")}
